  kids: {
    tasbihp: 'Jetzt lobst du Allah ganz oft hintereinander: „Subḥāna llāh, al-ḥamdu li-llāh, lā ilāha illa llāh, Allāhu akbar.“ Zähl leise mit den Fingern – wie ein kleines Lied, mit dem du Danke sagst.',
    sahw: 'Jeder vergisst mal etwas – auch im Gebet. Das ist nicht schlimm! Wenn du zum Beispiel vergessen hast, nach der zweiten Rakʿa zu sitzen, machst du am Ende einfach zwei extra Niederwerfungen. Damit ist alles wieder gut.',
    ghuslParts: {
      heart: 'Der Ghusl ist eine große Waschung für den ganzen Körper. Erwachsene machen ihn in bestimmten Fällen, viele auch am Freitag oder vor dem Fest. Sag in deinem Herzen: „Ich wasche mich jetzt ganz für Allah“ – und dann „Bismillāh“.',
      hands: 'Zuerst wäschst du die Hände – dreimal, auch zwischen den Fingern.',
      private: 'Dann wäschst du die Stellen, die die Unterhose bedeckt, mit der linken Hand gut sauber. Danach wäschst du die Hände noch einmal.',
      wuduAll: 'Jetzt machst du die ganz normale Gebetswaschung, die du schon kennst: Hände, Mund, Nase, Gesicht, Arme, Kopf, Ohren und Füße.',
      mouth: 'Spül den Mund richtig gut aus, damit das Wasser überall hinkommt – dreimal.',
      nose: 'Und auch die Nase: vorsichtig Wasser hineinziehen und wieder ausputzen, dreimal.',
      headPour: 'Jetzt gießt du Wasser über den Kopf, dreimal. Das Wasser soll bis auf die Haut unter den Haaren kommen – lange Haare gut durchkneten.',
      sideR: 'Dann die rechte Seite des Körpers: von der Schulter bis hinunter zum Fuß, dreimal. Rechts kommt immer zuerst.',
      sideL: 'Jetzt die linke Seite genauso, dreimal.',
      body: 'Zum Schluss schaust du, dass wirklich kein Fleckchen trocken bleibt: Bauchnabel, hinter den Ohren, unter den Armen, zwischen Fingern und Zehen. Wie unter der Dusche – nur ganz bewusst.',
    },
    tayammumParts: {
      heart: 'Manchmal gibt es kein Wasser – zum Beispiel auf einer Wanderung – oder jemand ist krank und darf nicht nass werden. Dann hilft Tayammum: Du machst dich mit reiner Erde bereit. Sag in deinem Herzen: „Ich mache Tayammum für das Gebet“ – und „Bismillāh“.',
      strike: 'Leg beide Hände flach auf saubere Erde, Sand oder einen Stein.',
      dust: 'Klopf die Hände leicht ab oder puste – du sollst nicht dreckig werden, die Erde soll deine Hände nur berühren.',
      tFace: 'Streich mit beiden Händen einmal über dein ganzes Gesicht, von der Stirn bis zum Kinn.',
      strike2: 'Leg die Hände noch einmal auf die Erde und klopf sie ab.',
      tArmR: 'Streich mit der linken Hand über deinen rechten Arm, von den Fingern bis zum Ellbogen.',
      tArmL: 'Und mit der rechten Hand über den linken Arm, bis zum Ellbogen. Fertig – jetzt darfst du beten!',
    },
    niyya: 'Stell dich ruhig hin und schau auf den Platz, wo gleich deine Stirn den Boden berührt. Sag in deinem Herzen: „Ich bete jetzt für Allah.“ Das ist die Niyya, die Absicht – du musst sie nicht laut sagen.',
    takbir: 'Heb beide Hände hoch, bis die Daumen fast die Ohren berühren, und sag: „Allāhu akbar“ – Allah ist größer als alles. Ab jetzt bist du im Gebet: Du redest nicht mehr mit anderen und schaust nicht herum.',
    opening: 'Leg die rechte Hand über die linke und steh ruhig wie ein Baum. Jetzt lobst du Allah ganz leise – so, wie man jemanden freundlich begrüßt, bevor man ihn um etwas bittet.',
    fatiha: 'Jetzt kommt die Fātiḥa, die wichtigste Sure. Sprich sie langsam, Wort für Wort. Bei jedem Vers antwortet dir Allah – du sprichst jetzt direkt mit Ihm.',
    sura: 'Nach der Fātiḥa sagst du eine kurze Sure, die du schon kannst, zum Beispiel Al-Ikhlāṣ: „Allah ist der Eine.“ Wenn du noch keine kannst, ist das nicht schlimm – unter „Suren lernen“ übst du sie Schritt für Schritt.',
    qunut: 'Jetzt kommt ein besonderes Bittgebet, das Qunūt. Du bittest Allah, dass Er dich auf den richtigen Weg führt, dich beschützt und dir hilft.',
    ruku: 'Sag „Allāhu akbar“ und beuge dich nach vorn. Dein Rücken ist gerade wie ein Tisch, die Hände liegen auf den Knien, und du schaust auf den Boden. Sag dreimal: „Subḥāna rabbiya l-ʿaẓīm“ – Gepriesen sei mein Herr, der Gewaltige.',
    itidal: 'Richte dich wieder ganz gerade auf und sag dabei: „Samiʿa llāhu li-man ḥamidah“ – Allah hört den, der Ihn lobt. Wenn du stehst: „Rabbanā wa laka l-ḥamd“ – unser Herr, Dir gebührt der Dank.',
    sujud: 'Sag „Allāhu akbar“ und geh langsam auf den Boden: erst die Knie, dann die Hände, dann Stirn und Nase. Jetzt bist du Allah ganz nah. Sag dreimal: „Subḥāna rabbiya l-aʿlā“ – Gepriesen sei mein Herr, der Höchste. Hier darfst du Ihm auch alles sagen, was dich freut oder bedrückt.',
    jalsa: 'Setz dich kurz auf, die Hände liegen auf den Oberschenkeln. Atme ruhig und sag: „Rabbi ghfir lī“ – mein Herr, vergib mir. Gleich geht es noch einmal auf den Boden.',
    tashahhud: 'Bleib sitzen. Jetzt sprichst du den Tashahhud: Du grüßt Allah, den Propheten ﷺ und alle guten Menschen. Wenn du sagst „Es gibt keinen Gott außer Allah“, hebst du den rechten Zeigefinger.',
    rise: 'Steh wieder auf und sag dabei „Allāhu akbar“. Eine neue Rakʿa beginnt – das ist wie eine neue Runde im Gebet, wieder mit Fātiḥa, Verbeugung und Niederwerfung.',
    salawat: 'Bleib sitzen und sprich die Ṣalawāt: Du bittest Allah, den Propheten Muhammad ﷺ und seine Familie zu segnen – so wie Er Ibrāhīm und seine Familie gesegnet hat.',
    dua: 'Jetzt darfst du Allah um Gutes bitten – für dich, deine Eltern, deine Freunde und alle Menschen. Zum Beispiel: „Unser Herr, gib uns Gutes in dieser Welt und im Jenseits.“',
    salam: 'Dreh den Kopf nach rechts und sag „As-salāmu ʿalaykum wa raḥmatu llāh“ – Friede sei mit euch. Dann nach links genauso. So endet jedes Gebet: mit einem Friedensgruß an alle.',
    shahada: 'Geschafft! Du bist jetzt sauber und bereit zum Beten. Zum Schluss sagst du das Glaubensbekenntnis: Es gibt keinen Gott außer Allah, und Muhammad ist Sein Gesandter.',
    wudu: 'Mit Wasser machst du dich sauber – außen, und auch dein Herz wird ruhig.',
    wuduParts: {
      heart: 'Bevor du anfängst, sag in deinem Herzen: „Ich wasche mich jetzt für das Gebet.“ Dann sprich leise „Bismillāh“ – im Namen Allahs. Und denk daran, Wasser zu sparen: Lass den Hahn nur laufen, solange du ihn brauchst.',
      hands: 'Wasch zuerst deine Hände bis zu den Handgelenken – dreimal. Reib auch zwischen den Fingern, so wie beim Händewaschen vor dem Essen. Fang immer mit der rechten Hand an.',
      mouth: 'Nimm mit der rechten Hand etwas Wasser in den Mund, spül ihn gut aus – die Backen dürfen sich dabei bewegen – und spuck das Wasser ins Becken. Das machst du dreimal.',
      nose: 'Zieh mit der rechten Hand ein wenig Wasser vorsichtig in die Nase – nicht zu fest! – und putz sie mit der linken Hand wieder aus. Auch das dreimal.',
      face: 'Jetzt das ganze Gesicht: von der Stirn, wo die Haare anfangen, bis unter das Kinn, und von einem Ohr bis zum anderen. Dreimal – und kein Fleckchen darf trocken bleiben, das ist Pflicht.',
      armR: 'Wasch deinen rechten Arm, von den Fingerspitzen bis über den Ellbogen. Der Ellbogen gehört dazu! Dreimal, danach kommt der linke Arm.',
      armL: 'Jetzt genauso den linken Arm: von den Fingerspitzen bis über den Ellbogen, dreimal.',
      head: 'Mach deine Hände nass und streich damit über den Kopf: von der Stirn nach hinten zum Nacken und wieder nach vorn. Hier wird nicht gewaschen, nur einmal darübergestrichen.',
      ears: 'Fahr mit den nassen Zeigefingern innen durch die Ohren und mit den Daumen hinten über die Ohrmuscheln. Einmal reicht.',
      footR: 'Jetzt der rechte Fuß – am besten im Sitzen auf dem Hocker. Wasch ihn bis über den Knöchel, dreimal. Vergiss die Zwischenräume der Zehen nicht: Mit dem kleinen Finger geht das gut.',
      footL: 'Zum Schluss genauso den linken Fuß, bis über den Knöchel und zwischen den Zehen, dreimal.',
    },
  },
